import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---- Custom CUDA kernel for element-wise addition (float) ----
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b)"
)

# ---- Custom CUDA kernel for ReLU (FP32) ----
relu_kernel_source = """
__global__ void relu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = fmaxf(input[idx], 0.0f);
    }
}

torch::Tensor relu_cuda(torch::Tensor a) {
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (a.numel() + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), out.data_ptr<float()>, a.numel());

    return out;
}
"""

relu_cpp_source = "torch::Tensor relu_cuda(torch::Tensor a);"

# Compile elementwise addition
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# Compile ReLU
relu = load_inline(
    name="relu_cuda",
    cpp_sources=relu_cpp_source,
    cuda_sources=relu_kernel_source,
    functions=["relu_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class Model(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(Model, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.conv2d(x)


class ModelNew(nn.Module):
    """
    Optimized version of Model.
    - Keeps the same Conv2d layer (unchanged).
    - Replaces activation with custom FP32 ReLU via `relu_cuda`.
    - Provides elementwise addition if needed via `elementwise_add`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        y = self.conv2d(x)
        return relu_cuda(y)
